-- ============================================================================

-- ============================================================
-- 社科类文本阅读（6个L4节点）parent: 社科类文本阅读(L3)
-- ============================================================

SET @l3_sheke = (SELECT id FROM knowledge_nodes WHERE subject_id = 20 AND name = '社科类文本阅读' AND level = 3 LIMIT 1);

UPDATE knowledge_nodes SET content =
'【一句话定义】\n论述文（议论文）是以议论为主要表达方式，通过摆事实、讲道理来阐明观点的一种文体。三要素是论点、论据和论证。\n\n【具体说明】\n① 论点：中心论点（全篇核心，通常在标题/开头/结尾）、分论点（支持中心论点的各层观点，常位于每段段首）。论点必须是明确的判断（陈述句），非疑问句或描述。\n② 论据：事实论据（具体事例/统计数据/"司马迁遭宫刑著《史记》"）、道理论据（名人名言/科学公理/"业精于勤荒于嬉"）。要求：真实、典型、充分、与论点契合。\n③ 论证方法（重点）：举例论证（用具体事例证明）、道理论证/引用论证（引用名人名言）、对比论证（正反对比突出观点）、比喻论证（用比喻方式论证·"学习如逆水行舟"）、因果论证（分析因果链条）、类比论证（用相似事物类比）。\n④ 论证结构：引论（开头）→本论（主体，分论点展开）→结论（结尾）。本论结构：并列式/递进式/对照式/总分式。\n\n【常见错误】\n1. 论点与论据混淆→论点是观点，论据是证明观点的材料\n2. 论证方法与修辞手法混淆→比喻论证是论证方法，比喻修辞是修辞手法\n3. 分不清举例论证和道理论证→举例用"事例"，道理用"名言/道理"\n\n【考试方向】\n选择题判断论证方法，或简答题"画线句子运用了什么论证方法，有何作用"。'
WHERE parent_id = @l3_sheke AND name = '论述文阅读（论点·论据·论证）';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n说明文是以说明为主要表达方式，介绍事物、解说事理的一种文体。考查重点是说明对象、说明方法和说明顺序的识别。\n\n【具体说明】\n① 说明对象与特征：事物说明文（介绍具体事物形状/构造/功能）、事理说明文（解说抽象事理的成因/规律）。读文时先明确说明对象和特征。\n② 说明方法（重点五种）：举例子（具体实例·"比如鲸是哺乳动物"·具体可感）、列数字（数据·"赵州桥全长50.82米"·准确有说服力）、作比较（两事物比较·突出特点）、分类别（分不同类别·条理清晰）、下定义（揭示本质·"人是能制造工具进行劳动的高等动物"·科学严密）。其他：打比方（生动）、作诠释（解释）、摹状貌（形象）。\n③ 说明顺序：时间顺序（按发展先后）、空间顺序（按位置关系·从上到下/从左到右/从外到里）、逻辑顺序（按内在联系·现象到本质/原因到结果/主要到次要）。\n④ 说明文语言特点：准确性（科学精确）、简洁性（言简意赅）、科学性（基于事实）。\n\n【常见错误】\n1. 作比较与打比方混淆→作比较是事物间比较（客观），打比方是比喻（生动）\n2. 下定义与作诠释混淆→下定义揭示本质（主谓可互换），作诠释仅解释某方面\n3. 说明顺序判断错误→看文章整体结构而非某段落\n\n【考试方向】\n选择题判断说明方法，简答题概括说明对象特征或分析说明顺序。'
WHERE parent_id = @l3_sheke AND name = '说明文阅读（说明方法·说明顺序）';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n信息筛选与整合是在阅读过程中快速定位关键信息、区分主次、归纳概括要点的能力。\n\n【具体说明】\n① 信息筛选三步法：第一步读题干（明确要找什么信息/关键词/限定条件）→第二步定位原文（回到原文找到对应语段）→第三步比对筛选（对比原文与选项，排除干扰项保留正确答案）。\n② 信息整合方法：摘取法（从原文直接摘录关键语句）、概括法（用自己的话归纳原文多个语句的核心）、合并法（将分散在多处相关的同类信息合并）。\n③ 常见干扰项类型：偷换概念（"主要因素"→"唯一因素"）、以偏概全（"某些/部分"→"全部"）、混淆时态（"将/可能"→"了/一定"）、无中生有（原文无此信息）、曲解文意（故意歪曲）、张冠李戴（把A的观点安到B头上）。\n④ 简答题答题步骤：审清题干关键词和限定范围→在原文中圈画相关信息→提取关键信息概括→检查是否全面/准确/简洁。\n\n【常见错误】\n1. 看到原文出现过的词语就选→"词对"不一定"意对"\n2. 选项和原文"差不多"就选→程度副词（所有/部分/可能/一定）是关键\n3. 概括类简答题照搬原文→需要用自己的话归纳\n\n【考试方向】\n客观题选出正确/不正确的一项（必考），主观题"请简要概括……"（4分左右）。'
WHERE parent_id = @l3_sheke AND name = '信息筛选与整合';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n分析推理是根据文本信息进行合理推断的能力，要求能够依据原文但不囿于原文，做出符合逻辑的判断。\n\n【具体说明】\n① 推理类型：直接推理（根据原文直接信得出结论）、间接推理（综合原文多处信息推断）、延伸推理（在原文基础上做合理延伸）。\n② 合理判断标准：于文有据（推理基础来自原文）、逻辑成立（过程符合逻辑）、范围适度（不超出合理范围）。\n③ 常见推理谬误（干扰项）：过度推断（"有A因素"→"只有A因素"）、强加因果（A和B并列→"A是B的原因"）、以偏概全（"部分人"→"所有人"）、真假不辨（混淆假设/推测与事实）、绝对化（"可能/往往"→"一定/全部"）。\n④ 判断技巧：遇到"一定/必然/所有/任何/全都"等绝对词高度警惕；遇到"可能/或许/往往/大概"等缓和词选项更可能正确；"据原文可知"题的答案一定在原文有依据。\n\n【常见错误】\n1. 生活经验干扰→"我觉得应该是这样"不能代替原文依据\n2. 选项偷换了程度/范围→"很多=所有""可能=一定"最常见陷阱\n3. 两个选项都"有道理"→选"根据原文可以推知的"，不选"无法判断的"\n\n【考试方向】\n选择题："根据原文内容，下列说法正确/不正确的一项是"（必考，3分）。'
WHERE parent_id = @l3_sheke AND name = '分析推理与判断';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n把握文章结构是理清段与段之间的逻辑关系，分析论证逻辑是理解作者如何一步步证明论点的思维过程。\n\n【具体说明】\n① 常见文章结构类型：总分式（总→分/分→总/总→分→总·最常见）、并列式（各段并列从不同角度论述）、递进式（层层深入·由浅入深·由现象到本质）、对照式（正反对比）。\n② 结构分析方法：找段落中心句（通常段首或段尾）、找过渡句/过渡段（提示前后关系·因果/转折/递进）、画段落层次图（理清脉络）、关注关联词和序列词（"首先/其次/最后""第一/第二""一方面/另一方面"）。\n③ 论证逻辑分析：演绎法（一般→个别·"所有金属导电→铜是金属→铜导电"）、归纳法（个别→一般·列举事例归纳结论）、类比法（个别→个别）。\n④ 段落作用分析：开头段（引出话题/提出论点/交代背景）、中间段（承上启下/展开论述/举例论证）、结尾段（总结全文/升华主题/照应开头）。\n\n【常见错误】\n1. 把并列结构当递进→看各段间是否有"更进一层"的逻辑关系\n2. 中心句找错→有时中心句不在段首而在段中或段尾\n3. "叙事≠论证"→议论文中叙述事例是对事实论据的陈述\n\n【考试方向】\n简答题："请简要分析本文的论证思路/结构""第X段有什么作用"。'
WHERE parent_id = @l3_sheke AND name = '文章结构与论证逻辑';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n考查在具体语境中理解重要词语和关键句子的含义，要求结合上下文分析其具体意义和在文中的作用。\n\n【具体说明】\n① "重要概念"的特征：反复出现的核心术语（如"文化自信""可持续发展"）、作者赋予特殊含义的词语（非日常含义）、有修饰/限定成分的概念（"真正的自由"≠"自由"）。\n② "关键句子"的类型：中心句（表达段落/文章核心）、过渡句（连接上下文）、议论句（表达作者观点态度）、含蓄句（含义深刻需解读）、修辞句（使用了修辞手法）。\n③ 含义理解方法：词语理解（词典义→语境义→作用）、句子理解（字面意思→联系上下文解读深层→把握表达意图）。\n④ 答题范式：含义题——"（词语/句子）在文中指……（具体含义），表现了/说明了……（作用）"；作用题——"内容上……（写了什么/表达了什么），结构上……（承上启下/铺垫/照应）"。\n\n【常见错误】\n1. 脱离语境架空解读→不看上下文凭自己的理解答题\n2. 停留在字面不挖深层→"太阳升起来了"可能还象征希望/新开始\n3. 概念理解与全文主旨脱节→核心概念往往与文章主旨紧密相关\n\n【考试方向】\n选择题选出正确理解的一项，简答题"谈谈你对画线句子的理解"（4-6分）。'
WHERE parent_id = @l3_sheke AND name = '重要概念与关键句理解';

SELECT 'v129b: 社科类阅读 6个L4节点完成' AS progress;

-- ============================================================
-- 文学作品阅读（7个L4节点）parent: 文学作品阅读(L3)
-- ============================================================

SET @l3_wenxue = (SELECT id FROM knowledge_nodes WHERE subject_id = 20 AND name = '文学作品阅读' AND level = 3 LIMIT 1);

UPDATE knowledge_nodes SET content =
'【一句话定义】\n小说是以塑造人物形象为中心，通过完整的故事情节和具体的环境描写来反映社会生活的一种文学体裁。人物、情节、环境是小说的三要素。\n\n【具体说明】\n① 人物形象：描写方法——正面描写（肖像·暗示性格、语言·体现身份性格、动作·展现心理、心理·揭示思想、细节·画龙点睛）、侧面描写（通过他人反应/环境衬托）。人物类型：主要人物（核心）与次要人物（推动情节/衬托主角）。分析角度：人物身份→性格特点→价值观念→社会意义。\n② 故事情节：四个阶段（开端→发展→高潮→结局）。线索（人物线索/事件线索/情感线索/物品线索）。叙述顺序（顺叙/倒叙/插叙/补叙）。\n③ 环境描写：自然环境（渲染气氛/烘托心情/推动情节/暗示主题）、社会环境（揭示社会根源/交代背景）。\n④ 主题思想：通过人物命运和情节发展揭示的人生感悟或社会思考。\n\n【常见错误】\n1. 人物形象分析只概括性格不举例→必须有原文描写做支撑\n2. 高潮判断错误→高潮是矛盾最集中最激烈的部分\n3. 环境描写作用答不全→可能同时有渲染+烘托+推动三重作用\n\n【考试方向】\n简答题："概括人物形象特点""分析环境描写的作用""本文叙述顺序有何效果"。'
WHERE parent_id = @l3_wenxue AND name = '小说阅读（人物·情节·环境）';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n散文是一种取材广泛、写法灵活、以抒发作者真情实感为特征的文学体裁，"形散神不散"是其本质特征。\n\n【具体说明】\n① 散文特征：形散（取材自由古今中外天南地北·结构灵活多种手法自由切换）、神不散（主题集中统一·有贯穿全文的情感线索·所有材料服务主题）、情景交融（景物描写融入主观情感·"一切景语皆情语"）。\n② 散文分类：叙事散文（记事写人为主·如《背影》，注意散文叙事重情感真实非塑造人物）、抒情散文（抒发情感·如《荷塘月色》）、哲理散文（阐发哲理·如《论快乐》）。\n③ 散文线索：人物线索（某个人物贯穿全文）、事件线索、情感线索（最常见·作者情感变化）、事物线索（某个物品串联·如"灯""窗""路"）、时空线索（按时间推移或空间转换）。\n④ 散文语言特点：优美性（用词精准文笔优美）、个性化（独特语言风格）、含蓄性（言有尽而意无穷）。\n\n【常见错误】\n1. 忘了找"神"→不能只看到材料繁杂还要找到统一主题\n2. 把散文中的叙事当小说读→散文叙事目的是抒情\n3. 不善于从景物中读出情感→"月亮是圆的"客观vs"月亮圆得让人想家"融情于景\n\n【考试方向】\n简答题："本文以什么为线索""分析形散神不散特点""景物描写表达了作者怎样的情感"。'
WHERE parent_id = @l3_wenxue AND name = '散文阅读（形散神聚·情景交融）';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n表现手法是作者在文学作品中使用的一系列艺术技巧，服务于主题表达和人物塑造。\n\n【具体说明】\n① 象征：用具体形象暗示抽象概念（高尔基《海燕》·海燕象征革命先驱；茅盾《白杨礼赞》·白杨象征抗日军民）。\n② 对比：将相反事物/方面对照，突出本质。\n③ 衬托（烘托）：正衬（以好衬好·美景衬好心情）、反衬（以反衬正·"以乐景写哀"热闹场景中独悲伤更显孤独、"蝉噪林逾静，鸟鸣山更幽"以动衬静）。\n④ 欲扬先抑：先贬后褒——使情节曲折、人物形象更丰满、对比更鲜明。\n⑤ 借景抒情（情景交融）：景物描写融入作者情感。\n⑥ 托物言志：通过描写物品表达志向/情操（周敦颐《爱莲说》·借莲花表达高洁志趣）。\n⑦ 虚实结合：实写眼前景/事+虚写想象/回忆/梦境——丰富内容拓展意境深化情感。\n⑧ 铺垫与伏笔：铺垫（为后文做准备使不突兀）、伏笔（前文暗示后文关键情节·增加悬念）。\n\n【常见错误】\n1. 象征与比喻混淆→象征是整体性的（全篇），比喻是局部性的（一个句子）\n2. 对比与衬托混淆→对比双方平等，衬托有主次之分\n3. 借景抒情与托物言志混淆→前者重在情感，后者重在志向/节操\n\n【考试方向】\n简答题："本文运用了哪些表现手法？结合文章分析""画线句子运用了什么表现手法，有何效果"。'
WHERE parent_id = @l3_wenxue AND name = '表现手法辨析';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n表达方式是作者采用的表述方法，包括记叙、描写、抒情、议论、说明五种，不同文体以不同表达方式为主。\n\n【具体说明】\n① 记叙：交代事件发生过程。六要素（时间/地点/人物/起因/经过/结果）。人称：第一人称（真实亲切但视野有限）、第二人称（拉近距离/抒情强）、第三人称（客观全面/不受限制）。\n② 描写：用生动语言对人物/景物/环境做具体描绘。对象分人物/景物/场面描写。角度分正面描写（直接写对象本身）和侧面描写（通过他人反应间接写）。方法：白描（简洁勾勒）vs工笔（细致入微）。作用：如见其人如临其境。\n③ 抒情：表达主观情感。直接抒情（直抒胸臆·"祖国啊，我亲爱的祖国！"）、间接抒情（借景/借物/借事/借理）。作用：感染读者、深化主题。\n④ 议论：对事物/人物进行评价阐明观点。在文学中常是画龙点睛的。特点：精练、有哲理性。作用：揭示本质、升华主题。\n⑤ 说明：简明扼要解说事物阐明事理（主要用于说明文）。\n⑥ 综合运用：记叙文以记叙为主兼用描写抒情；散文多种方式灵活结合；议论文以议论为主兼用记叙（事例作论据）。\n\n【常见错误】\n1. 五种表达方式混淆→记叙"发生什么"，描写"什么样子"，抒情"什么感受"，议论"什么道理"\n2. 表现手法与表达方式混淆→表现手法是具体技巧（象征/对比等），表达方式是五大类\n3. 正面描写与侧面描写分不清→正写直接写对象，侧面通过他人/他物间接表现\n\n【考试方向】\n简答题："画线句子运用了什么表达方式，有什么作用"。'
WHERE parent_id = @l3_wenxue AND name = '表达方式及其作用';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n人物形象分析是文学阅读的核心能力，要求从文本中提取关于人物性格、品质、情感的信息，进行全面准确的分析和概括。\n\n【具体说明】\n① 分析角度（五维度）：外貌（有时貌如其人有时表里不一）、语言（粗鲁话→粗犷性格、文言→知识分子）、动作（攥紧拳头→愤怒/决心）、心理（"他想…"内心活动）、细节（"手指的茧"→辛勤劳动的人）。\n② 正面描写和侧面描写：正面（直接写外貌/语言/动作/心理）、侧面（通过他人评价/环境映衬/其他人物对比间接写）。\n③ 答题模板：格式"XX是一个……的人。""从文中……（原文描写）可以看出他……（性格/品质）""从他……（行为/语言）可见他……"。要求：概括+分析，以概括为主（先概括性格特征），以分析为辅（引出对应原文）。\n④ 人物作用分析：主要人物（承载主题思想·作者表达核心）、次要人物（衬托主要人物/推动情节/揭示环境/作为线索）。\n\n【常见错误】\n1. 只贴标签不举例→"他是一个善良的人"没有原文支撑得分低\n2. 忽略人物变化→人物形象可能有发展变化（由懦弱变勇敢）要写出变化\n3. 次要人物忽视→次要人物也有分析价值\n\n【考试方向】\n简答题："请概括XX的人物形象特点"（4分）或"写XX有什么作用"（4分）。'
WHERE parent_id = @l3_wenxue AND name = '人物形象分析';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n语言品味是对文学作品中关键词语、句子的深层含义和表达效果的鉴赏分析，赏析是对修辞手法和句式表达效果的欣赏和评价。\n\n【具体说明】\n① 词语品味：选词精妙（"春风又绿江南岸"中"绿"字·色彩鲜明/动态感/化形容词为动词）、词语替换辨析（"轻风扶细柳"·"扶"换成"吹"行不行？"扶"有拟人效果）、叠词效果（"轻轻的我走了"·增强节奏感和抒情性）。\n② 句式品味：长短句结合（长句严密短句有力）、整散句结合（整句整齐有力散句灵活自然）、反问句/感叹句（增强语气感染力）。\n③ 赏析答题模板："运用了…修辞手法/表现手法，生动形象地写出了…（对象+特征），表达了作者…的感情（情感/主旨）"。示范："运用了比喻的修辞手法，把月亮比作圆盘，生动形象地写出了月亮的明亮圆满，表达了作者对中秋团圆的美好期许。"\n④ 常见修辞手法的赏析效果词：比喻（生动形象/化抽象为具体）、拟人（赋予灵性/生动活泼）、排比（增强语势/条理分明）、夸张（突出特征/感染力强）、反复（突出强调/加深印象）、对偶（形式整齐/音韵和谐）。\n\n【常见错误】\n1. 赏析只点手法不析效果→必须分析"写出了什么+表达了什么"\n2. 用空话套话代替具体分析→"使文章更加生动"太空泛\n3. 脱离语境孤立赏析→必须结合具体文本内容\n\n【考试方向】\n简答题："请赏析画线句子"（4分）或"XX一词有什么表达效果"（3分）。'
WHERE parent_id = @l3_wenxue AND name = '语言品味与赏析';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n主题是文学作品通过形象、情节和语言所表达的核心思想或情感倾向，概括主题是阅读理解的最终目标。\n\n【具体说明】\n① 主题含义层次：表层含义（文章直接写的是什么·人/事/景/物）、深层含义（表达了什么思想·人生感悟/社会思考/情感体验）、象征意义（作品中的形象象征了什么抽象概念）。\n② 主题把握方法：看标题（标题暗示主题方向·《背影》与父爱有关）、看开头结尾（开头点题/结尾升华·把握主题的关键位置）、看议论抒情句（作者直接表露态度的句子就是主题的钥匙）、看人物命运/情节结局（人物的最终命运暗示作者态度和主题）、看反复出现的词语/意象（反复出现就是作者想强调的）。\n③ 答题模板："本文通过叙述/描写……（主要内容），塑造了……（人物形象），表现了……（人物品质），表达了作者……（思想感情/态度），揭示了……（社会意义/人生哲理）"。要求：全面/准确/深刻。\n④ 常见主题类型：亲情主题（父母之爱/祖孙情）、成长主题（挫折与坚持/青春梦想）、社会主题（人性善恶/社会关怀）、人生哲理（坚持与放弃/得与失）、自然主题（人与自然/敬畏生命）。\n\n【常见错误】\n1. 主题概括过于笼统→"表达了作者对生活的热爱"太空泛\n2. 把故事梗概当主题→主题是"表达了什么思想"不是"写了什么故事"\n3. 忽略标题暗示→标题往往是精心设计的主题指示灯\n\n【考试方向】\n简答题："请概括本文的主题"（4-6分）或"结合全文谈谈对文章最后一段的理解"。'
WHERE parent_id = @l3_wenxue AND name = '主题理解与概括';

SELECT 'v129b: 文学作品阅读 7个L4节点完成' AS progress;

