SET @l3_shici = (SELECT id FROM knowledge_nodes WHERE subject_id = 20 AND name = '常见文言实词虚词' AND level = 3 LIMIT 1);

UPDATE knowledge_nodes SET content =
'【一句话定义】\n一词多义指同一个文言词语在不同的语境中有多个不同的义项，正确判断具体义项是读懂文言文的基础。\n\n【具体说明】\n① 常见多义实词举例：安（①安稳/安定②怎么/哪里③安置）；信（①诚信②相信③信物/凭证④随意⑤通"伸"）；故（①原因②旧的知识③故意④所以⑤老朋友）。\n② 义项判断技巧：语境推断法（结合前后文判断合理义项）、语法分析法（分析该词在句中充当什么成分）、成语联想法（现代成语中往往保留了古义）。\n③ 重点实词举例：爱（爱惜/吝惜）、被（遭受/通"披"）、兵（兵器/军队/战争）、朝（早晨/朝见/朝廷/朝代）、诚（真诚/确实/如果）、除（台阶/清除/授官）、辞（言辞/推辞/告别）、从（跟从/自/听从）、道（道路/道理/说/道义/方法）、度（量长短/揣度/度过/法度）。\n\n【常见错误】\n1. 只记一个义项→"故"只知"所以"不知其他\n2. 以今义理解古义→"牺牲玉帛"的"牺牲"不是今天的意思\n3. 不结合语境死记硬背→义项选择必须根据上下文确定\n\n【考试方向】\n选择题：选出"加点词解释正确/不正确的一项"（给四个文言语句含加点实词）。'
WHERE parent_id = @l3_shici AND name = '一词多义';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n古今异义指同一个词语在古代和现代汉语中意义不同，是文言文阅读的重要陷阱。\n\n【具体说明】\n① 词义扩大（古窄今宽）："江"古专指长江→今泛指江河；"河"古专指黄河→今泛指河流；"中国"古指中原地区→今指中华人民共和国。\n② 词义缩小（古宽今窄）："妻子"古指妻子和儿女→今仅指妻；"丈夫"古指成年男子→今指配偶；"金"古指所有金属→今指黄金。\n③ 词义转移（完全不同）："牺牲"古指祭祀牲畜→今指为正义而死；"卑鄙"古指地位低见识浅→今指品质恶劣；"交通"古指交错相通→今指运输邮电；"绝境"古指与世隔绝的地方→今指没有出路的境地；"可怜"古指可爱→今指值得怜悯。\n④ 感情色彩变化："爪牙"古指得力助手（褒）→今指坏人帮凶（贬）。\n⑤ 双音词陷阱：古汉语两个单音词连用≠现代汉语一个双音词——"地方"古义"地"+"方"（土地方圆）、"其实"古义"其"+"实"（它的果实/它实际上）。\n\n【常见错误】\n1. 以今义代入古义→养成"遇到熟悉词先怀疑是否古今异义"的习惯\n2. 双音词当现代汉语理解→"妻子"在古代是"妻+子"两个词\n3. 感情色彩变化不敏感→"爪牙"在古代是褒义\n\n【考试方向】\n选择题选出"加点词与现代汉语意义相同/不相同的一项"。'
WHERE parent_id = @l3_shici AND name = '古今异义';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n词类活用指在特定语境中，某个词临时改变了它原本的词性，充当了其他词类的语法功能。\n\n【具体说明】\n① 名词作动词（最常见）："沛公军霸上"→"军"作动词"驻军"；"范增数目项王"→"目"作动词"用眼睛示意"；"左右欲刃相如"→"刃"作动词"用刀杀"。判断标志：名词前有副词（乃/遂/不）修饰或后面带宾语。\n② 名词作状语：表处所（"夜驰之沛公军"→在夜里）、表比喻（"天下云集响应"→像云像回声）、表态度（"吾得兄事之"→像对待兄长一样）、表工具（"箕畚运于渤海之尾"→用箕畚）。\n③ 形容词作名词："将军身被坚执锐"→"坚"坚固的铠甲、"锐"锋利的武器；"温故而知新"→"故"旧知识、"新"新知识。\n④ 使动用法：动词使动（"项伯杀人，臣活之"→使…活）、形容词使动（"春风又绿江南岸"→使…变绿）、名词使动（"生死而肉骨"→使…长肉）。\n⑤ 意动用法：形容词意动（"孔子登东山而小鲁"→认为…小）、名词意动（"孔子师郯子"→以…为师）。\n\n【常见错误】\n1. 把词类活用当本义理解→按名词理解"军"而不理解是"驻军"\n2. 使动与意动混淆→使动客观"使宾语变了"，意动主观"认为宾语怎么样"\n3. 名词作状语翻译遗漏→"夜驰"的"夜"必须译出"在夜里"\n\n【考试方向】\n选择题选出"加点词用法与例句相同的一项"或"没有词类活用的选项"。'
WHERE parent_id = @l3_shici AND name = '词类活用';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n通假字是古代汉语中用读音相同或相近的字代替本字的用字现象。\n\n【具体说明】\n① 考试高频通假字："说"通"悦"（高兴）、"见"通"现"（出现/显露·"风吹草低见牛羊"）、"反"通"返"（返回）、"属"通"嘱"（嘱咐·"属予作文以记之"）、"内"通"纳"（接纳·"距关，毋内诸侯"）、"被"通"披"（穿/覆盖·"将军身被坚执锐"）、"华"通"花"、"坐"通"座"（座位·"满坐寂然"）。\n② 通假字判断方法：按本字解释不通→尝试同音/近音字替换→换字后语境通顺即为通假。\n③ 更多高频通假字："要"通"邀"（邀请）、"倍"通"背"（违背）、"蚤"通"早"、\n"惠"通"慧"（聪明·"甚矣汝之不惠"）、"衡"通"横"、\n"曾"通"层"。\n\n【常见错误】\n1. 通假字当本字硬解释→"说"硬解为"说话"而非"高兴"\n2. 通假字与词类活用混淆→通假字本质是"用错了字"，词类活用是"改变了词性"\n3. 漏记通假字→需要单独积累记忆\n\n【考试方向】\n选择题选出"不是通假字的选项"或翻译题中要求译出通假字的本字。'
WHERE parent_id = @l3_shici AND name = '通假字';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n文言虚词是不具有实际词汇意义、主要表示语法关系的词。考纲15个虚词中，"之""其""以""而"考查频率最高。\n\n【具体说明】\n① "之"：代词（代人/事/物·"学而时习之"）、助词-的（"沛公之参乘"）、助词-取消句子独立性（主谓间·"臣之壮也，犹不如人"）、宾语前置标志（"何陋之有"）、动词-去/到（"辍耕之垄上"）、音节助词（"久之"）。\n② "其"：代词-他/那（"其妻献疑曰"）、指示代词-其中（"其一犬坐于前"）、副词-揣测/大概（"其皆出于此乎"）、副词-反问/难道（"其可怪也欤"）、连词-如果。\n③ "以"：介词-用/凭/因为（"以勇气闻于诸侯""不以物喜"）、介词-按照（"余船以次俱进"）、连词-来/用来（"作《师说》以贻之"）、连词-而（"木欣欣以向荣"）、动词-认为。\n④ "而"：并列（"敏而好学"）、递进（"博学而日参省"）、转折（"青于蓝而青于蓝"·却）、修饰（"终日而思"·地）、承接（"学而时习之"·就）、因果（"积善成德而神明自得"）。\n\n【常见错误】\n1. "之"取消独立性用法最难判断→主谓间"之"去掉句子依然通顺\n2. "以"介词和连词混淆→后跟名词是介词，后跟动词是连词\n3. "其"揣测和反问语气判断错误\n\n【考试方向】\n选择题选出"加点虚词意义和用法相同/不相同的一项"。'
WHERE parent_id = @l3_shici AND name = '常见虚词（之·其·以·而）';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n继续讲解"于""为""乃""则"四个常见虚词的主要用法。\n\n【具体说明】\n⑤ "于"：介词-在（"战于长勺"）、对于（"于其身也，则耻师焉"）、比（"冰，水为之而寒于水"·比水更冷）、被（"受制于人"）。\n⑥ "为"：介词-替/为了（"公为我献之"）、被（"为天下笑者"·被天下人耻笑）、动词-做/是（"可以为师矣"）、句末语气词-呢（"何辞为"）。\n⑦ "乃"：副词-于是/就（"乃令符离人葛婴将兵"）、竟然（"乃不知有汉，无论魏晋"）、才（"乃悟前狼假寐"）、判断词-是（"当立者乃公子扶苏"）。\n⑧ "则"：连词-就（"学而不思则罔"）、却（"于其身也，则耻师焉"）、判断-就是/原来是（"此则岳阳楼之大观也"）。\n⑨ 其他重要虚词简述："者"（…的人/表停顿）、"所"（…的地方/所字结构）、"也"（表判断/表陈述）、"焉"（于此/哪里/语气）、"乎"（吗/于）、"且"（将要/暂且/而且）、"若"（如果/像/比得上）、"因"（于是/凭借）、"与"（和/给/参与）、"相"（互相/偏指一方/看）。\n\n【常见错误】\n1. "于"的比较用法翻译为"在"→"寒于水"是"比水冷"\n2. "为"的被动用法与"被"混淆→"为天下笑"即"被天下人耻笑"\n3. "乃"的"竟然"义容易漏掉→"乃不知有汉"必须译出"竟然"\n\n【考试方向】\n选择题判断虚词意义和用法，或翻译题中准确译出虚词作用。'
WHERE parent_id = @l3_shici AND name = '常见虚词（于·为·乃·则）';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n文言句式指文言文中不同于现代汉语的固定句型结构，判断句和被动句是结构特殊的句子类型。\n\n【具体说明】\n**判断句**：① 格式："…者，…也"（"陈胜者，阳城人也"·最标准）、"…，…也"（省略者·"夫战，勇气也"）、"…者，…"（省略也）、无标志判断（"刘备，天下枭雄"）、用"为/是"（"如今人方为刀俎"）、用"乃/则"（"当立者乃公子扶苏""此则岳阳楼之大观也"）。② 注意：文言"是"通常是指示代词"这"非判断词。\n**被动句**：① 格式："为…所…"（"茅屋为秋风所破"）、"见…于…"（"吾长见笑于大方之家"）、"为…"（"为天下笑者"）、"被"（"忠而被谤"·出现较晚）、无标志被动（语义被动·"帝感其诚"=天帝被他的诚心感动）。\n\n【常见错误】\n1. 看到"是"就认为判断句→先秦"是"多是指示代词"这"\n2. 无标志被动句忽略→"帝感其诚"不是"天帝感动了他的诚心"\n3. "为"的多义混淆→根据语境判断"做/是/替/被"\n\n【考试方向】\n选择题选出"与例句句式相同的一项"，翻译题中准确译出判断句和被动句。'
WHERE parent_id = @l3_shici AND name = '文言句式（判断句·被动句）';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n倒装句指语序与现代汉语不同的文言句式（宾语前置/状语后置/定语后置），省略句指省略了某些句子成分的句式。\n\n【具体说明】\n**倒装句**：\n① 宾语前置：否定句中代词宾语前置（"古之人不余欺也"→不欺余）、疑问句中疑问代词宾语前置（"大王来何操？"→操何）、"之/是"为前置标志（"何陋之有"→有何陋、"唯利是图"→唯图利）、介词宾语前置（"何以战？"→以何战）。\n② 状语后置（介宾短语放动词后面）："战于长勺"→于长勺战（在长勺作战）；"青，取之于蓝"→于蓝取之；"投以骨"→以骨投。\n③ 定语后置（定语放中心词后面）："马之千里者"→千里马之马；"蚓无爪牙之利，筋骨之强"→利之爪牙、强之筋骨；"求人可使报秦者"→可使报秦之人。\n**省略句**：\n① 省略主语（最常见）："（）见渔人，（）乃大惊"→省略"桃花源里的人"。\n② 省略宾语："一鼓作气，再（）而衰，三（）而竭"→省略"鼓"。\n③ 省略介词："将军战（）河北，臣战（）河南"→省略"于"（在）。\n\n【常见错误】\n1. 倒装句不调语序→翻译时必须按现代汉语语序调整\n2. 定语后置识别不出→"马之千里者"误译成"马跑了一千里"\n3. 省略成分不补出→翻译出来的句子缺主语/宾语表意不明\n\n【考试方向】\n选择题选出与例句句式相同的选项，翻译题中准确处理倒装和省略。'
WHERE parent_id = @l3_shici AND name = '文言句式（倒装句·省略句）';

SELECT 'v129b: 文言实词虚词 8个L4节点完成' AS progress;

-- ============================================================
-- 文言文翻译与理解（3个L4节点）parent: 文言文翻译与理解(L3)
-- ============================================================

SET @l3_fanyi = (SELECT id FROM knowledge_nodes WHERE subject_id = 20 AND name = '文言文翻译与理解' AND level = 3 LIMIT 1);

UPDATE knowledge_nodes SET content =
'【一句话定义】\n文言文翻译是将古代汉语准确转化为现代汉语的过程，遵循"直译为主、意译为辅"的基本原则，以"信、达、雅"为质量标准。\n\n【具体说明】\n① 翻译原则：直译为主（逐词对应翻译保持用词和句式）、意译为辅（直译不通时灵活处理）。信（准确·忠实原文不增不减）、达（通顺·符合现代汉语规范）、雅（优美·在信达基础上追求优美，对口考试以信达为主）。\n② 翻译步骤：第一步通读（通读全句/全段，把握大意语境）→第二步标注（圈画关键词：实词义项/虚词用法/通假字/词类活用/特殊句式）→第三步逐词（逐词确定意思，古语替换为现代汉语）→第四步调整（调整语序·倒装句还原、补出省略成分、处理通假字）→第五步检查（通读译文，检查通顺和漏译）。\n③ 翻译得分点：关键实词翻对（每词1-2分）、关键虚词作用译出（"而"表转折必须译"却"）、特殊句式处理（判断句加"是"，倒装句调序，省略句补出）、语句整体通顺。\n\n【常见错误】\n1. 只译大意不逐词→丢失关键实词得分点\n2. 不加"是"的判断句→"陈胜者阳城人也"必须译为"陈胜是阳城人"\n3. 倒装句不调→"何陋之有"译为"有什么简陋的呢"不能译"什么简陋的有"\n\n【考试方向】\n翻译题（4-6分）：给1-2句文言文翻译成现代汉语，按得分点逐一给分。'
WHERE parent_id = @l3_fanyi AND name = '翻译原则与步骤';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n翻译技巧"五字法"（留、补、换、调、删）是文言文翻译的核心操作规范，确保翻译既准确又通顺。\n\n【具体说明】\n① "留"——保留不译：人名（沛公/项王/诸葛亮）、地名（咸阳/江东/岳阳）、官名/年号/国号（太守/贞观/大宋）、器物专名（玉斗/白璧）。原因：专有名词没有对应的现代说法，强行翻译反而失真。\n② "补"——补充缺失：补主语（省略的主语·"（）见渔人"补"桃花源里的人"）、补宾语（"一鼓作气，再（）而衰"补"鼓"）、补介词（"将军战（）河北"补"于/在"）、补关联词（根据逻辑关系补"因为/所以/但是"）。\n③ "换"——替换转化：古语→现代（"吾"→"我""汝"→"你""曰"→"说"）、单音→双音（"师"→"老师""学"→"学习""思"→"思考"）、通假→本字（"说"通"悦"→"高兴"）、词类活用→正常表达（"军霸上"→"在霸上驻军"）。\n④ "调"——调整语序：宾语前置→正常（"何陋之有"→"有何陋"）、状语后置→正常（"战于长勺"→"于长勺战"）、定语后置→正常（"马之千里者"→"千里马之马"）。\n⑤ "删"——删除不译：发语词（"夫战，勇气也"→不译"夫"）、音节助词（"久之"→只译"久"）、取消独立性"之"（"臣之壮也"→"我壮年的时候"不译"之"）。\n\n【常见错误】\n1. 专有名词也翻译→原文用"沛公"有其语境（尊称）\n2. 省略不补→翻译出来的句子缺头少尾\n3. 倒装不调→保留古汉语语序不通顺\n\n【考试方向】\n翻译题中综合运用五字法，评分关注是否恰当处理特殊句式/通假字/省略。'
WHERE parent_id = @l3_fanyi AND name = '翻译技巧（留·补·换·调·删）';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n文意理解是在翻译的基础上，把握文言文的基本内容、人物形象、思想感情和写作目的的综合能力。\n\n【具体说明】\n① 理解文章基本内容：概括事件（谁+做了什么事+结果如何）、理清情节（划分段落层次·把握开端→发展→高潮→结局）、把握人物关系（君臣/朋友/师生/亲属）。\n② 分析人物形象：从言行概括（人物的语言反映什么性格？行为体现什么品质？）、从他人评价概括（文中其他人如何评价这个人？）、从作者态度概括（作者通过议论句/抒情句表达了什么态度？）。\n③ 把握作者观点和态度：关注议论抒情句（"臣以为…""故曰…"直接表达观点）、关注结尾（结尾往往是作者观点的总结或升华）、关注史评（"太史公曰""异史氏曰"直接表达史家态度）。\n④ 理解写作目的：借古讽今（写历史为了讽喻现实）、托物言志（写物为了表达志向）、劝谏说理（写文章为了规劝或阐明道理）、记事抒情（记事为了抒发情感）。\n⑤ 选择题常见陷阱：人物/事件张冠李戴、时间/地点/因果错乱、无中生有（原文完全未提及）、以偏概全（部分人说成全部）。\n\n【常见错误】\n1. 用现代观念评古代人物→不能脱离历史背景\n2. 内容概括过于啰嗦→一句话能说清的不说三句\n3. 因果倒置→"因为B所以A"而原文是"因为A所以B"\n\n【考试方向】\n选择题："下列对原文有关内容的概括和理解不正确的一项是"（3分）。'
WHERE parent_id = @l3_fanyi AND name = '文意理解与概括';

SELECT 'v129b: 翻译与理解 3个L4节点完成' AS progress;

-- ============================================================
-- 话题作文（7个L4节点）parent: 话题作文(L3)
-- ============================================================

SET @l3_zuowen = (SELECT id FROM knowledge_nodes WHERE subject_id = 20 AND name = '话题作文' AND level = 3 LIMIT 1);

UPDATE knowledge_nodes SET content =
'【一句话定义】\n审题是准确理解题目要求、把握写作范围和方向的第一步；立意是在审题基础上确立文章的中心论点。审题错误是作文最致命的问题。\n\n【具体说明】\n① 审题方法：圈画关键词法（圈出所有关键词逐一分析含义和限定）、类型识别（命题作文·标题即中心；话题作文·在范围内自定角度；材料作文·从材料中提取核心立意）、限制定位（文体要求/字数要求/特殊要求）。\n② 立意原则：准确（紧扣题目·不偏题不跑题）、明确（中心论点清楚不含糊）、深刻（有思辨深度·不停留常识层面）、新颖（角度有新意·不落俗套）。\n③ 立意优劣举例：话题"以坚持为话题写议论文"。肤浅："坚持就是胜利"——常识级缺乏深度。较深①："坚持不是盲目固执，而是有方向有方法的执着"——有思辨。较深②："真正的坚持是在正确方向上日复一日的积累，而非以战术上的勤奋掩盖战略上的懒惰"——深刻具体。\n④ 审题误区：关键词替换（"坚持"写成"勤奋"·偷换概念偏题）、不看要求（要求"结合经历"却全无个人事例）、脱离材料（"自定立意"不等于"可以完全脱离材料"）。\n\n【常见错误】\n1. 看了一眼话题就开始写→不看限定条件\n2. 中心论点太抽象→"要努力才能成功"太空泛\n3. 立意与标题脱节→文章内容和标题各说各的\n\n【考试方向】\n话题作文或材料作文约45分。审题立意是决定作文等级的基石。'
WHERE parent_id = @l3_zuowen AND name = '审题立意';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n论点是议论文中要证明的核心观点；论据是用来证明论点的事实材料和道理依据。论点如"骨"，论据如"肉"，两者缺一不可。\n\n【具体说明】\n① 论点的要求：正确（符合主流价值观）、鲜明（态度明确不模棱两可）、集中（一篇一个中心论点）、新颖（自己的独到见解）、陈述句式（"…是…""…应该…""…需要…"）。\n② 分论点设置：从不同角度/层面支持中心论点，一般2-3个，层层递进或并列展开，段首明确亮出。\n③ 论据要求：真实（确有/不能编造）、典型（有代表性）、充分（每个分论点1-2个）、新颖（不翻来覆去用爱迪生/居里夫人/司马迁）。\n④ 论据类型：事实论据（历史人物·苏轼被贬仍豁达/司马迁忍辱著《史记》、时代楷模·袁隆平/钟南山/张桂梅、身边事例、数据统计）；道理论据（名人名言·孔子/鲁迅/培根、成语典故·水滴石穿/愚公移山、科学公理）。\n⑤ 论据使用：概述为主（不能像记叙文展开·简洁概括）、扣住论点（叙述后一定要分析如何证明论点）、不堆砌（多个论据分别支撑不同分论点）。\n\n【常见错误】\n1. 论点与论据脱节→举了司马迁例子但没有分析"这说明了什么"\n2. 论据陈旧→千篇一律的"爱迪生发明灯泡"\n3. 论据代替论证→罗列事例不加分析变成"事例汇编"\n\n【考试方向】\n议论文主体考查。能否提出明确论点并用恰当论据支撑是关键。'
WHERE parent_id = @l3_zuowen AND name = '议论文论点与论据';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n论证结构是议论文的组织框架，指分论点之间、论据与论点之间的逻辑排列关系，决定了文章的条理性和说服力。\n\n【具体说明】\n① 并列式（横向展开）：各分论点从不同侧面平行论述中心论点。示例："读书有三大益处"→①增长知识②陶冶情操③启迪智慧。优点：条理清晰易操作。注意：分论点间不能有包含关系。\n② 递进式（纵向深入）：由浅入深、由表及里、由现象到本质。示例："诚信至关重要"→①什么是诚信→②诚信对个人的意义→③诚信对社会的意义→④如何践行。优点：思辨性强有深度。注意：递进层次要清晰。\n③ 对照式（正反对照）：从正反两面论述。示例："坚持是成功的基石"→正面·坚持者终获成功（正例）→反面·放弃者一事无成（反例）。优点：对比鲜明论证有力。\n④ 总分式（总分总）：开头总提→中间分论点展开→结尾总结升华。最常见结构，可与其他结构结合使用。\n⑤ 结构选择建议：初学者优先并列式（易组织）或对照式（素材丰富），有思辨能力的选递进式（展现深度）。\n\n【常见错误】\n1. 结构混乱→分论点间逻辑关系不清\n2. 分论点包含关系→"勤奋学习"包含"认真听课"\n3. 并列式但分论点重复→三个分论点说的其实是同一件事\n\n【考试方向】\n阅卷老师快速扫描文章时首先看论证结构是否清晰。结构清楚的文章容易得高分。'
WHERE parent_id = @l3_zuowen AND name = '议论文论证结构';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n开头是文章的"门面"，决定阅卷老师的第一印象；结尾是文章的"收官"，决定读完后的最后感受。\n\n【具体说明】\n**开头技巧**（约80-120字，1.5-2段）：\n① 名言引入法：引用与主题相关的名人名言——"苏轼曾言：古之立大事者，不惟有超世之才，亦必有坚忍不拔之志。千百年来正是坚忍不拔四个字让无数平凡生命绽放光彩。"\n② 故事引入法：用简短故事引出话题——"一百年前没有人相信人类可以飞上天空；五十年前没有人相信电脑可以走进千家万户。然而这一切都已成为现实。是什么力量推动了改变？是创新。"\n③ 设问引入法：用设问引起思考——"什么是责任？是挺身而出的勇气，还是默默坚守的执着？"\n④ 排比引入法：用排比句增强气势——"自信是黑暗中的明灯，自信是沙漠中的清泉，自信是风雨中的大伞。"\n**结尾技巧**（约80-100字，1段）：\n① 总结升华法：概述要点提升到更高层面。\n② 首尾呼应法：回扣开头形成闭环。\n③ 呼吁号召法：向读者发出号召——"让我们从今天做起做一个有责任有担当的新时代青年。"\n④ 哲理结尾法：用充满哲理的句子收束——"人生如登山，重要的不是站在哪一级台阶上，而是你还在向上攀登。"\n\n【常见错误】\n1. 开头太啰嗦→绕了大圈才点题\n2. 结尾草草收场→"这就是我对坚持的认识"毫无力量\n3. 首尾脱节→开头提A结尾说B\n\n【考试方向】\n直接影响"结构"和"语言表达"得分，好的开头结尾提升1-2个分数档。'
WHERE parent_id = @l3_zuowen AND name = '开头与结尾技巧';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n语言表达技巧包括用词准确贴切、句式灵活多变、恰当使用修辞，使文章语言从"通顺"提升到"有文采"。\n\n【具体说明】\n① 词语运用：精准用词（不说"好看"说"赏心悦目"，不说"伤心"说"黯然神伤"）、善用成语（"日复一日的坚持终将水滴石穿"）、避免口语（少用"搞""弄""太"，多用"实施""开展""非常"）。\n② 句式变化：长短句结合（长句严密短句有力）、整散句结合（整句排比对偶整齐有力·散句灵活自然）、反问句增气势、感叹句强情感。\n③ 修辞运用：比喻化抽象为具体（"坚持如一座灯塔指引我们穿越迷雾"）、排比增强语势、引用增添文化底蕴（"正如鲁迅先生所言：世上本没有路，走的人多了也便成了路"）、反问加强说服力。\n④ 过渡技巧：段落间要有过渡句（"不仅如此""然而""反观现实""由此看来"），论据与论点间要有分析（"这个事例充分说明了……""这从侧面印证了……"）。\n⑤ 避免的问题：空洞口号式语言（"我们要努力奋斗创造美好明天"太虚）、矫揉造作式语言（生硬堆砌华丽词）、网络语言（"YYDS""绝绝子"不合文体）。\n\n【常见错误】\n1. 全文句式单一→全是"我认为……我觉得……所以要……"\n2. 堆砌辞藻脱离内容→金玉其外败絮其中\n3. 缺少过渡硬转硬接→段与段之间读起来跳跃\n\n【考试方向】\n"有文采"是发展等级的重要加分项，语言表达好的文章比语言平淡的分数高3-5分。'
WHERE parent_id = @l3_zuowen AND name = '语言表达技巧';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n写作素材是支撑作文内容的事实材料、名言典故和思想观点。丰富的储备和恰当的运用是写出内容充实文章的基础。\n\n【具体说明】\n① 素材来源：课本素材（教材中的课文/人物/典故·《劝学》学习观、《师说》尊师观）、历史文化（古代名人·孔子/屈原/司马迁/苏轼/岳飞/文天祥）、时代楷模（袁隆平/钟南山/张桂梅/黄旭华/南仁东）、生活素材（身边人/事/自己的经历）、名言警句（古今中外有哲理或启发性的名言）。\n② 素材整理方法：按主题分类（坚持类/创新类/责任类/诚信类/感恩类/梦想类/挫折类/爱国类…），每个主题准备2-3个名人事例+1-2条名言+1个人生活事例，建立"素材卡片"（人物+事迹+可论证的主题+简短分析）。\n③ 素材运用原则：精选非堆砌（一个段落一个核心素材+分析）、概述非详叙（议论文中事例50-80字概括）、分析非罗列（用了素材之后一定要有分析·"这个事例说明…"）、扣题非游离（素材为论证论点服务）。\n④ 中职生重点记忆素材：坚持（司马迁著《史记》、愚公移山、水滴石穿）、责任担当（范仲淹"先天下之忧而忧"、林则徐虎门销烟、抗疫医护人员）、学习成长（荀子《劝学》"学不可以已"、韩愈《师说》）、创新（四大发明到现代科技、袁隆平杂交水稻）、挫折逆境（苏轼被贬仍豁达、贝多芬失聪仍创作）。\n\n【常见错误】\n1. 素材太少→只会用爱迪生和居里夫人内容单调\n2. 素材罗列不分析→三个事例说完没分析\n3. 素材不扣论点→袁隆平更适合论证"创新"或"为国奉献"而非"坚持"\n\n【考试方向】\n内容充实是基础等级重要得分点。有具体素材的文章比空泛议论分数明显更高。'
WHERE parent_id = @l3_zuowen AND name = '写作素材积累与运用';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n卷面与书写规范包括字迹清晰工整、标点正确使用、段落合理划分、格式符合要求，直接影响阅卷老师的评分第一印象。\n\n【具体说明】\n① 字迹规范：字迹清晰（每个字笔画清楚·不潦草不连笔）、大小适中（约占方格纸2/3）、行列整齐（行行对齐不歪斜·字间距均匀）、字体选择（正楷最佳行楷亦可·杜绝草书）。注意：字迹不清不会直接扣分但会导致阅卷老师"看不清而少给分"。\n② 标点规范：标点占格（每个标点一格·省略号和破折号占两格）、书写位置（左下角或中间偏下）、引号规范（双引号在外单引号在内）、书名号（《》用于书名/篇名/报刊名）。常见错误：逗号写成点号、一逗到底不分段、感叹号连用不严肃。\n③ 段落划分：全文5-7段为宜（开头1段80-120字、分论点各1段120-150字、结尾1段80-100字）。每段开头空两格，段落匀称（避免超过200字的巨型段落或一句话一行的碎片段落）。\n④ 格式与卷面：标题居中（第一行正中）、字数控制（600字底线不可破）、保持整洁（少涂改·修改用横线划掉不涂墨团）。\n⑤ 阅卷心理：字迹工整的作文在同等水平下比字迹潦草的作文高2-4分；扫描阅卷时字迹潦草影响更大。\n\n【常见错误】\n1. 字太小/太大→太小看不清太大显空洞\n2. 一逗到底→只有逗号和句号，无丰富标点\n3. 段落不分或分段过多→一大段让人喘不过气，或一句话一段显得碎\n4. 涂改过多→破坏卷面整洁和可读性\n\n【考试方向】\n字迹和卷面不单独给分，但影响基础等级"表达"得分，间接影响发展等级。'
WHERE parent_id = @l3_zuowen AND name = '卷面与书写规范';

